(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025+t*0.5)*8+Math.cos(sy*0.02-t*0.4)*6;
  const w2y = Math.cos(sy*0.025-t*0.45)*8+Math.sin(sx*0.022+t*0.55)*6;
  const wx = sx+w2x, wy = sy+w2y;
  const src = [];
  for(let i=0;i<8;i++){const a=i*0.7854+t*0.15,r=100+Math.sin(t*0.4+i*1.3)*30;src.push([cx+Math.cos(a)*r,cy+Math.sin(a)*r,0.08+Math.sin(t*0.3+i)*0.02,2+Math.sin(t*0.5+i*0.7)*0.4]);}
  for(let i=0;i<5;i++){const a=i*1.2566-t*0.1,r=60+Math.cos(t*0.5+i*2.1)*20;src.push([cx+Math.cos(a)*r,cy+Math.sin(a)*r,0.12+Math.cos(t*0.35+i)*0.03,1.5+Math.cos(t*0.6+i*0.9)*0.3]);}
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp]of src){const d=Math.sqrt((wx-sX)**2+(wy-sY)**2);aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);hS+=Math.sin(d*f*1.3-t*sp*0.8+3);}
  const n=13,act=aS/n,inh=iS/n,harm=hS/n;
  const bg=(Math.sin(wx*0.04+wy*0.025+t*0.8)+Math.sin(wx*0.03-wy*0.04+t*1.1))/2+Math.sin((wx+wy)*0.12+t*2.5)*0.2+Math.sin((wx-wy)*0.1-t*2)*0.2+Math.sin(wx*0.08+wy*0.06+t*1.5)*0.15;
  const dist=Math.sqrt((wx-cx)**2+(wy-cy)**2),ang=Math.atan2(wy-cy,wx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.03-ang*5+t*0.8)*0.2;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+harm*0.15)*2.2);
  const cell=Math.tanh((Math.sin(wx*0.15)*Math.sin(wy*0.15)+Math.sin((wx+wy)*0.1+t)*0.5)*1.5)*0.3;
  const turb=(Math.sin(wx*0.06+Math.sin(wy*0.05+t*0.7)*3+t*0.9)+Math.sin(wy*0.07+Math.sin(wx*0.04-t*0.5)*2-t*1.1))*0.15;
  const blend=reaction*0.6+cell*0.2+turb*0.2,v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,40,85],[15,75,115],[25,130,135],[80,170,140],[190,185,80],[220,140,60],[195,75,65],[150,40,70],[90,20,55],[40,12,48],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.7?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow=Math.max(0,1-Math.abs(reaction)*1.2)*0.15;
  const vig=1-Math.sqrt((x-cx)**2+(y-cy)**2)/350*0.25;
  return[Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)*vig)|0,Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30)*vig)|0,Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*60)*vig)|0];
}
